package com.weaponsregistration.inventory.model;import com.weaponsregistration.core.model.CoreEntity;import jakarta.persistence.*;
@Entity@Table(name="erp_recall_item",uniqueConstraints={@UniqueConstraint(columnNames={"recall_id","asset_id"}),@UniqueConstraint(columnNames={"recall_id","lot_id"})})public class RecallItem extends CoreEntity{@ManyToOne(optional=false)@JoinColumn(name="recall_id",nullable=false)public Recall recall;@ManyToOne@JoinColumn(name="asset_id")public AssetItem asset;@ManyToOne@JoinColumn(name="lot_id")public StockLot lot;@Column(nullable=false)public String action;}
